import mongoose from 'mongoose';

const ballEventSchema = new mongoose.Schema({
  // _id is auto-generated by Mongoose
  
  match_id: { 
    type: mongoose.Schema.Types.ObjectId, 
    ref: 'Match', 
    required: true 
  },
  inningsNumber: { type: Number, required: true },
  overNumber: { type: Number, required: true },
  ballNumberInOver: { type: Number, required: true },
  
  batter_id: { 
    type: mongoose.Schema.Types.ObjectId, 
    ref: 'Player', 
    required: true 
  },
  bowler_id: { 
    type: mongoose.Schema.Types.ObjectId, 
    ref: 'Player', 
    required: true 
  },
  
  runsFromBat: { type: Number, default: 0 },
  extras: {
    type: { type: String, enum: ['WD', 'NB', 'LB', 'B', null], default: null },
    runs: { type: Number, default: 0 }
  },
  
  isWicket: { type: Boolean, default: false },
  wicketDetails: {
    type: { type: String, enum: ['BOWLED', 'CAUGHT', 'RUN_OUT', 'STUMPED', 'LBW', null], default: null },
    batter_id: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Player',
      default: null
    },
    fielder_id: { 
      type: mongoose.Schema.Types.ObjectId, 
      ref: 'Player', 
      default: null 
    },
  },
  
  timestamp: { type: Date, default: Date.now }
});

const BallEvent = mongoose.model('BallEvent', ballEventSchema);

export default BallEvent;